  /// Times [body] like [ElapsedUs], adding the spike when spiked.
  int call(void Function() body) {
    final sw = Stopwatch()..start();
    body();
    sw.stop();
    calls++;
    return sw.elapsedMicroseconds +
        (_spiked.contains(calls) ? (spikeMs * 1000).round() : 0);
  }
}

